insert into menu_items (id, category, name_en, name_ar, description_en, description_ar, price, image, available, options, sort_order)
values
  ('dish-chicken-biryani', 'biryani', 'Royal Chicken Dum Biryani', 'برياني دجاج ملكي', 'Slow-cooked fragrant basmati rice layered with marinated tender chicken, saffron, caramelised onions, and royal whole spices. Served with cooling cucumber raita and spicy salan.', 'أرز بسمتي عطري مطهو على نار هادئة مع دجاج متبل طري وزعفران وبصل مكرمل وتوابل ملكية، يقدم مع الرايتا والمرق.', 24, '/images/chicken-biryani.jpg', true, '[{"id":"portion","name":"Portion Size","type":"single","required":true,"choices":[{"id":"single","name":"Regular (1 Person)","price":0},{"id":"family","name":"Family Feast (3-4 Persons)","price":45}]},{"id":"spice","name":"Spice Level","type":"single","required":false,"choices":[{"id":"mild","name":"Mild","price":0},{"id":"medium","name":"Medium Spicy","price":0},{"id":"spicy","name":"Authentic Hot","price":0}]},{"id":"addons","name":"Add-ons","type":"multiple","required":false,"choices":[{"id":"extra-raita","name":"Extra Raita & Salan","price":4},{"id":"extra-egg","name":"Boiled Egg (2 pcs)","price":4}]}]'::jsonb, 0),
  ('dish-beef-biryani', 'biryani', 'Nawab Beef Biryani', 'برياني لحم بقري نوابي', 'Succulent chunks of prime beef marinated in house spices, layered over aromatic aged long-grain basmati rice and sealed to slow-cook to melt-in-mouth perfection.', 'قطع لحم بقري فاخرة متبلة ببهارات القصر ومطهوة مع أرز بسمتي معتق طويل الحبة.', 28, '/images/beef-biryani.jpg', true, '[{"id":"spice","name":"Spice Level","type":"single","required":false,"choices":[{"id":"medium","name":"Medium Spicy","price":0},{"id":"spicy","name":"Royal Spicy","price":0}]},{"id":"addons","name":"Add-ons","type":"multiple","required":false,"choices":[{"id":"extra-raita","name":"Extra Raita","price":3},{"id":"fried-onions","name":"Crispy Golden Onions & Cashews","price":5}]}]'::jsonb, 1),
  ('dish-egg-biryani', 'biryani', 'Spiced Egg Biryani', 'برياني بيض متبل', 'Golden roasted farm eggs seasoned with turmeric, chili, and ground spices, rested gently atop deeply aromatic saffron and mint infused biryani rice.', 'بيض محمر بتوابل الكركم والفلفل الحار موضوع على أرز البرياني المعطر بالزعفران والنعناع.', 18, '/images/egg-biryani.jpg', true, '[]'::jsonb, 2),
  ('dish-kabsa-mandi', 'biryani', 'Imperium Traditional Mandi / Kabsa', 'مندي / كبسة إمبيريوم التقليدية', 'Authentic Arabian slow-steamed Mandi spiced rice served with your choice of golden tender charcoal chicken or fall-apart braised lamb, accompanied by zesty Daqoos tomato salsa.', 'أرز مندي عربي تقليدي مطهو على البخار مع اختيارك من الدجاج المحمر أو لحم الضأن الطري مع صلصة الدقوس.', 32, '/images/kabsa.jpg', true, '[{"id":"meat","name":"Meat Selection","type":"single","required":true,"choices":[{"id":"chicken","name":"Whole Half Chicken","price":0},{"id":"lamb","name":"Braised Lamb Shank / Cut","price":16}]},{"id":"sauce","name":"Sauce & Garnish","type":"multiple","required":false,"choices":[{"id":"daqoos","name":"Extra Daqoos Spicy Salsa","price":3},{"id":"garlic","name":"Creamy Garlic Toum","price":3},{"id":"nuts","name":"Roasted Almonds & Raisins","price":5}]}]'::jsonb, 3),
  ('dish-grilled-half-chicken', 'grills', 'Charcoal Grilled Half Chicken', 'نصف دجاج مشوي على الفحم', 'Marinated in lemon, crushed garlic, and middle-eastern herbs, flame-blistered over open charcoal. Served with house garlic toum, pickles, and hot stone-baked pita.', 'دجاج متبل بالليمون والثوم والأعشاب ومشوي على الفحم، يقدم مع الثومية والمخلل والخبز الساخن.', 26, '/images/grilled-chicken.jpg', true, '[{"id":"style","name":"Preparation Style","type":"single","required":true,"choices":[{"id":"arabic-garlic","name":"Arabic Herb & Garlic","price":0},{"id":"peri-peri","name":"Spicy Peri-Peri Glaze","price":2}]},{"id":"sides","name":"Side Selection","type":"single","required":true,"choices":[{"id":"pita-fries","name":"Fresh Pita & French Fries","price":0},{"id":"spiced-rice","name":"Aromatic Spiced Mandi Rice","price":4}]}]'::jsonb, 4),
  ('dish-bbq-grilled-fish', 'grills', 'Imperial BBQ Grilled Whole Fish', 'سمك مشوي على الفحم بخلطة إمبيريوم', 'Fresh Arabian Gulf catch butterfly-split, coated in signature spiced chili-tamarind marinade, and slow-charred over hickory embers. Bursting with smoky citrus flavours.', 'سمك طازج من الخليج العربي متبل بخلطة الشطة والتمر هندي ومشوي على الفحم مع نكهات الليمون المدخنة.', 42, '/images/bbq-fish.jpg', true, '[{"id":"sides","name":"Served With","type":"single","required":true,"choices":[{"id":"rice","name":"Fluffy Spiced Rice & Lemon Wedges","price":0},{"id":"fries-bread","name":"Crisp Golden Fries & Arabic Bread","price":0}]}]'::jsonb, 5),
  ('dish-grilled-chicken-spiced-rice', 'grills', 'Grilled Chicken on Spiced Rice', 'دجاج مشوي على أرز مبهر', 'Tender boneless chicken breast fillets seared over glowing charcoal with Persian saffron marinade, served atop a generous platter of fragrant cardamom spiced rice.', 'قطع صدور دجاج مشوية بتتبيلة الزعفران تقدم على طبق سخي من الأرز المبهر بالهيل.', 30, '/images/grilled-chicken-rice.jpg', true, '[]'::jsonb, 6),
  ('dish-black-pepper-beef-fry', 'mains', 'Black Pepper Beef Fry (Kerala Roast)', 'لحم بقري محمر بالفلفل الأسود', 'A legendary South Indian specialty: tender beef strips slow-roasted with cracked Malabar black peppercorns, roasted coconut slivers, shallots, and fresh curry leaves.', 'لحم بقري مطهو على الطريقة الهندية مع الفلفل الأسود المطحون وقطع جوز الهند والبصل وأوراق الكاري.', 28, '/images/black-pepper-beef.jpg', true, '[{"id":"bread","name":"Bread Accompaniment","type":"single","required":false,"choices":[{"id":"none","name":"No Bread","price":0},{"id":"parotta","name":"2x Kerala Layered Parotta","price":4},{"id":"roti","name":"2x Whole Wheat Roti","price":3}]}]'::jsonb, 7),
  ('dish-beef-curry', 'mains', 'Traditional Slow-Simmered Beef Curry', 'كاري اللحم البقري التقليدي', 'Tender beef morsels gently braised in a thick, velvety onion, tomato, ginger, and toasted coriander gravy. Deep, hearty, and aromatic.', 'لحم بقري طري مطهو ببطء في مرق غني من الطماطم والزنجبيل والكزبرة المحمصة.', 26, '/images/beef-curry.jpg', true, '[]'::jsonb, 8),
  ('dish-chicken-kadai', 'mains', 'North Indian Kadai Chicken', 'دجاج كاداي الهندي', 'Succulent chicken tossed in a traditional iron wok with crisp bell peppers, tomatoes, and coarsely crushed coriander seeds and dry red chilies.', 'دجاج مطهو في ووك حديدي مع الفلفل الرومي والطماطم وبذور الكزبرة المحمصة.', 25, '/images/chicken-kadai.jpg', true, '[]'::jsonb, 9),
  ('dish-chicken-65', 'mains', 'Crispy Imperium Chicken 65', 'دجاج 65 المقرمش', 'Crispy bite-sized spiced chicken morsels deep-fried to a fiery crimson crunch and tossed with fresh green chilies, yogurt, and aromatic tempered curry leaves.', 'قطع دجاج مقرمشة بتتبيلة حارة مميزة مع الفلفل الأخضر والزبادي وأوراق الكاري العطرية.', 22, '/images/chicken-65.jpg', true, '[{"id":"style","name":"Serving Style","type":"single","required":true,"choices":[{"id":"dry","name":"Crispy Dry Snack","price":0},{"id":"gravy","name":"Semi-Gravy Sauce","price":3}]}]'::jsonb, 10),
  ('dish-chicken-manchurian', 'mains', 'Indo-Chinese Chicken Manchurian', 'دجاج مانشوريان', 'Golden crisp chicken meatballs bathed in a glossy, tangy dark soya sauce glaze with crushed garlic, fresh ginger, and chopped scallions.', 'كرات دجاج مقلية متبلة ومغموسة في صوص الصويا والثوم والزنجبيل والبصل الأخضر.', 24, '/images/chicken-manchurian.jpg', true, '[]'::jsonb, 11),
  ('dish-shrimp-noodles', 'chinese', 'Wok-Tossed Shrimp Hakka Noodles', 'نودلز الروبيان بالووك', 'High-heat wok-tossed egg noodles loaded with succulent Gulf prawns, shredded cabbage, crisp carrots, and dark soy-sesame glaze.', 'نودلز محمرة على نار عالية مع روبيان الخليج الطازج والخضار المشكلة وصوص الصويا والسمسم.', 28, '/images/shrimp-noodles.jpg', true, '[{"id":"spice","name":"Chili Sauce Level","type":"single","required":false,"choices":[{"id":"classic","name":"Classic Hakka (Mild)","price":0},{"id":"schezwan","name":"Fiery Schezwan Chili","price":2}]}]'::jsonb, 12),
  ('dish-double-chicken-cheese-burger', 'burgers', 'Double Chicken Cheese Burger', 'دبل تشيكن تشيز برغر', 'Twin crispy breaded chicken breasts stacked high with melted American cheddar, crunchy iceberg lettuce, pickled gherkins, and smoked secret house sauce in a toasted brioche bun.', 'قطعتان من صدور الدجاج المقرمشة مع الجبنة الأمريكية الذائبة والخس والصلصة الخاصة في خبز البريوش المحمص.', 24, '/images/burger.jpg', true, '[{"id":"meal","name":"Make it a Meal","type":"single","required":false,"choices":[{"id":"sandwich-only","name":"Burger Only","price":0},{"id":"combo-meal","name":"Combo: Crinkle Fries & Soft Drink","price":8}]},{"id":"extras","name":"Extra Toppings","type":"multiple","required":false,"choices":[{"id":"extra-cheese","name":"Extra Cheddar Slice","price":3},{"id":"jalapenos","name":"Spicy Pickled Jalapeños","price":2}]}]'::jsonb, 13),
  ('dish-beef-burger', 'burgers', 'Imperium Gourmet Beef Burger', 'غورميه بيف برغر', '100% prime chargrilled beef patty topped with aged cheddar, caramelized balsamic onions, beef bacon jam, and garlic aioli on a buttered sesame bun.', 'شريحة لحم بقري مشوية على الفحم مع الجبنة المعتقة والبصل المكرمل وصوص الثوم الخاص.', 22, '/images/beef-burger.jpg', true, '[]'::jsonb, 14),
  ('dish-grilled-chicken-burger', 'burgers', 'Charcoal Grilled Chicken Burger', 'برغر دجاج مشوي على الفحم', 'Herb-infused flame-grilled tender chicken breast, sliced ripe tomatoes, fresh arugula, melted provolone cheese, and honey-mustard mayonnaise.', 'صدر دجاج مشوي متبل بالأعشاب مع الجبن الذائب والخضار وصوص الخردل بالعسل.', 20, '/images/grilled-chicken-burger.jpg', true, '[]'::jsonb, 15),
  ('dish-mint-lime-mojito', 'drinks', 'Royal Mint Lime Mojito', 'موخيتو الليمون والنعناع الملكي', 'Freshly muddled garden mint, freshly squeezed zesty lime juice, organic pure cane sugar, and chilled sparkling soda poured over crushed ice crystals.', 'نعناع طازج مهروس مع عصير الليمون المنعش وسكر القصب والصودا الفوارة مع الثلج المجروش.', 14, '/images/mojito.jpg', true, '[{"id":"flavor","name":"Mojito Infusion","type":"single","required":true,"choices":[{"id":"classic","name":"Classic Lime & Fresh Mint","price":0},{"id":"passion","name":"Passionfruit & Lime","price":3},{"id":"strawberry","name":"Wild Strawberry & Mint","price":3}]}]'::jsonb, 16)
